const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
let ptr = 0;
function nextInt() { return parseInt(data[ptr++], 10); }

const mod = 1000000007n;

const dp = new Array(55);
for (let a = 0; a < 55; a++) {
    dp[a] = new Array(55);
    for (let b = 0; b < 55; b++) {
        dp[a][b] = new Array(205).fill(0n);
    }
}
const c = new Array(55);
