function max(a, b) { return a < b ? b : a; }

function getC(i, j) {
    if (i < 0 || j < 0 || i >= 55 || j >= 55) return 0n;
    return c[i][j];
}

function main() {
    let n = nextInt();
    let lim = nextInt();
    let A = 0, B = 0;
    let i, j, k, ii, jj;
    for (i = 0; i < n; i++) {
        const fk = nextInt();
        if (fk === 50) A++;
        else B++;
    }
    dp[A][B][0] = 1n;
    c[0][0] = 1n;
    for (i = 1; i <= 50; i++) {
        for (j = 0; j <= i; j++) {
            c[i][j] = getC(i - 1, j - 1) + getC(i - 1, j);
        }
    }
    for (k = 1; k <= 4 * n; k++) {
        for (i = A; i >= 0; i--) {
            for (j = B; j >= 0; j--) {
