                                    dp[i][j][k] += (dp[ii][jj][k - 1] * c[ii][ii - i] * c[jj][jj - j]) % mod;
                                    dp[i][j][k] %= mod;
                                }
                            }
                        }
                    }
                } else {
                    for (ii = 0; ii <= i; ii++) {
                        let f = lim - (i - ii) * 50;
                        if (f >= 0) {
                            f = Math.floor(f / 100);
                            f = max(j - f, 0);
                            for (jj = f; jj <= j; jj++) {
                                if (i !== ii || j !== jj) {
                                    dp[i][j][k] += (dp[ii][jj][k - 1] * c[A - ii][i - ii] * c[B - jj][j - jj]) % mod;
                                    dp[i][j][k] %= mod;
                                }
                            }
                        }
                    }
                }
                if (dp[0][0][k] !== 0n) {
                    console.log(k);
                    console.log(dp[0][0][k].toString());
                    return;
                }
            }
        }
    }
    console.log("-1\n0");
}

main();
